import { React, Fragment, useState, useEffect} from "react"
import { trackPromise } from "react-promise-tracker"
import axios from "axios"


const CancelRequest = props => {

  // passed parameter
  const {userList, setDisplayAlert, convertToLocal, superUserMode, convert2MMDDYY, setRefDetails} = props   

  // new add in this page
  const [racf, setRACF] = useState("")
  const [refList, setRefList] = useState([])
  const [selectedRef, setSelectedRef] = useState("")

  const [leaveType, setLeaveType] = useState("N/A")
  const [entitledDays, setEntitledDay] = useState("N/A")
  const [periodStart, setPeriodStart] = useState("N/A")
  const [periodEnd, setPeriodEnd] = useState("N/A")

  function handleRACF(event) {
    const { value } = event.target 
    const uppercaseValue = value.toUpperCase()
    setRACF(uppercaseValue)
  }

  function handleRefNo(event) {
    const { value } = event.target 
    setSelectedRef(value)
  }

  useEffect(() => {

    trackPromise(
      axios({
        url: "/eleave/api/getAllSpecialRef",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({'racf': racf, 'super_mode': superUserMode, 'localTime': convertToLocal(Date.now())} )      
      }
    )
    .then(response => response.data)
    .then(response => {          
       setRefList(response)
    }),
    "getRefListinCancel"
    )
  }, [racf, superUserMode, convertToLocal])

  const handleCancel = event => { 

    if (!window.confirm(`Are you sure you want to cancel ${selectedRef}?`)) {         
        return null     
      }
    trackPromise(
      axios({
        url: "/eleave/api/cancelRequest",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },          
        data: JSON.stringify({'ref_no': selectedRef, 'racf': racf})      
      }
    )
    .then(response => response.data)
    .then(response => {
      setDisplayAlert({ message: "Requisition cancelled successfully ", position: 4, timeout: 4000, color: "alert__green" })
    })
    .catch(error =>  {                             
      //console.log("Error status", error.response.status,  error.response.data.error_message)     // can also checking using error.response.status 
      setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 4000, color: "alert__red" })
    }),
    "cancelOtherLeave"
    )
  }

  useEffect(() => {

    trackPromise(
      axios({
        url: "/eleave/api/getRefDetails",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({'ref_no': selectedRef} )      
      }
    )
    .then(response => response.data)
    .then(response => {     
      setRefDetails(response[0])
      setLeaveType(response[0].leave_name)
      setEntitledDay(response[0].entitled_days.toFixed(1))
      setPeriodStart(convert2MMDDYY(response[0].period_start))
      setPeriodEnd(convert2MMDDYY(response[0].period_end))
    }),
    "getRefDetails"
    )
  }, [selectedRef, superUserMode, convert2MMDDYY, setRefDetails])


  return (
    <Fragment>
        
      <div> 
            <div className="separator">Cancel Reference</div>
            
            <div className="cancelsp_type_grid">

                <div className="cancelsp_type_area_a cancelsp_type_grid_a">
                Applicant:
                <select style={{width: '30rem', height:"25px"}} onChange={handleRACF} id="specialLeave_select" className="clickable" value={racf} >                
                <option value="" disabled> - </option>
                {userList && userList.map((user, index) => (
                  <option key={index} value={user.racf}>
                    {user.name} ({user.racf})
                  </option>
                ))}
                </select>
                </div>

                <div className="cancelsp_type_area_b cancelsp_type_grid_b">
                Approval #:
                <select style={{width: '14rem', height:"25px"}} onChange={handleRefNo} id="specialLeave_select" className="clickable" value={selectedRef} >                
                <option value="" disabled> - </option>
                {refList.map((ref) => (<option key={ref.ref_no} value={ref.ref_no}> {ref.ref_no}</option>))}
                </select>
                </div>

                <div className="cancelsp_type_area_c cancelsp_type_grid_c" style={{ borderBottom: "2px solid gray", marginLeft: 0, marginRight: 0 }}>
                  <div><strong>Leave Details</strong></div>
                </div>


                <div className="cancelsp_type_area_d cancelsp_type_grid_d">
                  Leave Type : {leaveType}
                </div>     

                <div className="cancelsp_type_area_e cancelsp_type_grid_e">
                  Entitled Days : {entitledDays}
                </div>     

                <div className="cancelsp_type_area_f cancelsp_type_grid_f">
                  Allowed Period: {periodStart} - {periodEnd}
                </div> 

            </div>   
            <button id="cancelsp_button" onClick={handleCancel}>
                  Cancel
            </button>
      </div>
    </Fragment>
  )
  }

export default CancelRequest