import React, { useState, Fragment, useEffect } from "react"
import ShowAlert from "./components/ShowAlert"
import EnterRequest from "./components/EnterRequest"
import CancelRequest from "./components/CancelRequest"

import ShowSpinner from "./components/ShowSpinner"

const Requisition = props => {

  const { currentRacf, userProfile, superUserMode, convertToLocal, alert, setDisplayAlert, convert2MMDDYY} = props     

  const [office, setOfficeList] = useState([])
  const [leaveType, setLeaveType] = useState([])
  const [userList, setUserList] = useState([])
  const [refDetails, setRefDetails] = useState([])

  useEffect(() => {

    fetch("eleave/api/getoffice", {
      method: "GET"
      })
      .then(response => response.json())
      .then(response => {
        setOfficeList(response)
      })

      fetch("eleave/api/getSpecialLeave", {
        method: "GET"
      })
        .then(response => response.json())
        .then(response => {
          setLeaveType(response)
      })

      fetch("eleave/api/getUserList", {
        method: "POST"
      })
        .then(response => response.json())
        .then(response => {
          let nUserList = response['userList']
          // First sort the array
          nUserList.sort(function (a, b) {
            // note : must change the string back to date object for comparison
            if (a.name < b.name) return -1   // ascening order by name
            else return 1
          })            
          setUserList(nUserList)  
      })


  }, [])

  return (
    <Fragment>

      <div className="subHeading"> Requisition </div>

      <EnterRequest userProfile={userProfile} currentRacf={currentRacf} office={office} setOfficeList={setOfficeList} leaveType={leaveType} setLeaveType={setLeaveType}
                    setDisplayAlert={setDisplayAlert} userList={userList}
      />

      <CancelRequest userProfile={userProfile} currentRacf={currentRacf} office={office} setOfficeList={setOfficeList} leaveType={leaveType} setLeaveType={setLeaveType}
                    setDisplayAlert={setDisplayAlert} userList={userList} superUserMode={superUserMode} convertToLocal={convertToLocal} convert2MMDDYY={convert2MMDDYY}
                    refDetails={refDetails} setRefDetails={setRefDetails}
      />

      {alert.position === 1 ? (
        <div className="flex-row">
          <div className="flex-large">
            <ShowAlert alert={alert} />
          </div>
        </div>
      ) : null}


      {alert.position === 4 ? (
                  <div className="flex-row">
                    <div className="flex-large">
                      <ShowAlert alert={alert} />
                    </div>
                  </div>
      ) : null}
      <ShowSpinner position={4} />

    </Fragment>
  )
}
export default Requisition
