import { React, useState, Fragment } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./ShowSpinner"
import DatePicker from "react-datepicker"
import { v4 as uuidv4 } from "uuid"

 
const EnterLeave = props => {

  const {year, racf, office, superUserMode, leaveType, setDisplayAlert, setRefreshPage, sharePointID, sharePointFiles, leaveList, setLeaveList, refDetails} = props 

  const [startLeaveDate, setStartLeaveDate] = useState("")
  const [endLeaveDate, setEndLeaveDate] = useState("")
  const [startPeriod, setStartPeriod] = useState("Full Day")
  const [endPeriod, setEndPeriod] = useState("Full Day")  

  const weekday= ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

  // This is needed to mitigate the dates between browser (local time) and server (Mongo DB)
  // When date (date.getTime) is selected, the date is based on UTC 00:00.  That could be the next day. 
  // Therefore, the offset has to be calcualted and be used to minus the date  
  const dateToString = (date, pos) => {      
    if (!date) { return}
    const userTimezoneOffset = date.getTimezoneOffset() * 60000;
    const d = new Date(date.getTime() - userTimezoneOffset);
    //console.log('d', d.toISOString().substring(0,10))
    if (pos ===1) {
      setStartLeaveDate(d.toISOString().substring(0,10))     
      //if (endLeaveDate.length === 0) {
      setEndLeaveDate(d.toISOString().substring(0,10))     
      //}
    }
    else
    {
      setEndLeaveDate(d.toISOString().substring(0,10))          
    }
    
  }
  
  // This is needed to mitigate the dates between browser (local time) and server (Mongo DB)
  // When date (date string) is captured, it is based on UTC 00:00. So the local time could become the previous day. 
  // Therefore, the offset has to be calcualted and be used to add to the date string   

  const stringToDate = dateString => {    
    let d = dateString       
    if (d === "") {      
      return
      //d = new Date()    
      //const userTimezoneOffset = d.getTimezoneOffset() * 60000;
      //d = new Date(d.getTime() - userTimezoneOffset);                 
    }
    else {
      d = new Date(dateString)         
      const userTimezoneOffset = d.getTimezoneOffset() * 60000;
      d = new Date(d.getTime() + userTimezoneOffset);               
    }
    return d        
  }
  
  const isoToShort = s => {
     return  s.slice(5,7) + "/" + s.slice(8,10) + "/" + s.slice(2,4)
  }   
     
   
  
  const handleDelLeave =  (id)  => {   
    setLeaveList(prev => prev.filter(x=>(x.id !==id) ))           
  }

  const handleStartPeriod =   event => {     
    const { value } = event.target
    setStartPeriod(value)           
  }

  const handleEndPeriod =   event => {   
    const { value } = event.target    
    setEndPeriod(value)             
  }

  const handleClearLeave =  ()  => {   
    setStartLeaveDate("")
    setEndLeaveDate("")    
    setStartPeriod("Full Day")
    setEndPeriod("Full Day")
  }
  
  const handleSubmitLeave = (updateDB) =>   {   
    
    if (startLeaveDate === endLeaveDate) {           
      if ( ( (startPeriod==="Full Day"?"PM":startPeriod) > (endPeriod==="Full Day"?"PM":endPeriod) ) || (  (startPeriod==="PM") && (endPeriod==="Full Day") ) )  {              
        setDisplayAlert({ message: "Please check your time period!", position: 1, timeout: 3000, color: "alert__red" })
        return
      }
    }

    if (startLeaveDate > endLeaveDate) {                   
        setDisplayAlert({ message: "Your start date of application is earlier than your end date!", position: 1, timeout: 3000, color: "alert__red" })
        return
    }

    const oLeaveList =  [...leaveList]
    let nLeaveList
    
    if (updateDB) {    
      if (!window.confirm('Are you sure you want to submit?')) {         
        return null     
     }
      // if Update DB is true - then it is a submit request, it doesn't require to insert a new line
        nLeaveList =  [...leaveList]        
    }
    else {
      nLeaveList = oLeaveList.concat({ "id": uuidv4(), startLeaveDate, startPeriod, endLeaveDate, endPeriod})
    }
    

    let applying = []
    let applyingScreen = []

    nLeaveList.forEach((e) => {                
        applying.push({ 'startDate' : e.startLeaveDate,  
                                   'startTime' : e.startPeriod==="Full Day" ? "AM" : e.startPeriod,                                   
                                   'endDate'   : e.endLeaveDate,    
                                   'endTime'   : e.endPeriod==="Full Day" ? "PM" : e.endPeriod 
                                 })
        applyingScreen.push({ 'startDate' : e.startLeaveDate,  
                                   'startTime' : e.startPeriod,                                   
                                   'endDate'   : e.endLeaveDate,    
                                   'endTime'   : e.endPeriod 
                                 })

    });
    
    const entireLeaveRequest = {
          "year": Number(year),
          "racf": racf,
          "office": office,
          "type": leaveType,
          "applying" : applying,
          "applyingScreen" : applyingScreen,
          "superUser":superUserMode,
          "sharePointId" : leaveType === "LVE04"? sharePointID:"",
          "otherLeaveRef" : leaveType === "LVE15"? [refDetails] : "",
          "updateDB" : updateDB,
          "timeZone" :  Intl.DateTimeFormat().resolvedOptions().timeZone           
    }

    //console.log('entire',JSON.stringify(entireLeaveRequest)    )
    //console.log('sharePointFiles',sharePointFiles  )

    if (sharePointFiles.length === 0 && leaveType==="LVE04") {
        setDisplayAlert({ message: "Please upload medical document!", position: 1, timeout: 4000, color: "alert__red" })
        return
    }
    
    if (nLeaveList) {

      //console.log('entireLeaveRequest',entireLeaveRequest)
      //        
      trackPromise(
        axios({
          url: "/eleave/api/applyleave",
          method: "POST",
          headers: {
            "Content-type": "application/json",
            api: "yes"         
          },          
          data: JSON.stringify(entireLeaveRequest)      
        }
      )
      .then(response => response.data)
      .then(response => {
        if (!(updateDB))   //  insert only             
            {//console.log('response', response)                   
             const calendarDay = response['result'][0]['calendarDay']
             const workday = response['result'][0]['workday']
             //console.log('return from db', calendarDay, workday)
             const  len_leaveList = leaveList.length
             const  nLeavelist_entry =  [...nLeaveList][len_leaveList]                          
             nLeaveList[len_leaveList] = { ...nLeavelist_entry, calendarDay, workday } 
             setLeaveList(nLeaveList)
             
             if (response['Warnings'] !== '') {
             setDisplayAlert({ message: response['Warnings'], position: 4, timeout: 6000, color: "alert__orange" })  
             } 
            }
        else {
             setDisplayAlert({ message: "Application submitted.  Please wait for subsequent approval by your people leader. ", position: 4, timeout: 4000, color: "alert__green" })        
             setLeaveList([])             
             setRefreshPage(x=>!x)      /// force refresh of eleave balance
        }            
                
      })
      .catch(error =>  {                             
        console.log("Error status", error.response.status,  error.response.data.error_message)     // can also checking using error.response.status 
        if (error.response.data.error_message.includes('Incorrect parameters')) {
          setDisplayAlert({ message: "It seems you haven't had a single leave entry", position: 1, timeout: 4000, color: "alert__red" })
        }
        else {
          setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 4000, color: "alert__red" })
        }
      }),
      "typeOfLeave"
      )
      return () => {
        //setBalance({}) // This worked for me            
      }     
    }
  }

  return (
    <Fragment>
      <div>
        <div>                        

            <div className="separator">Apply Leave</div>         

            <div className="enterLeave_grid_c">                       
                    <div>Start Date</div>                    
                    <DatePicker className="datePicker" dateFormat="MM/dd/yy" selected={stringToDate(startLeaveDate)} onChange={date => dateToString(date,1)}/>                   
                    <select onChange={handleStartPeriod} id="enterLeave_startPeriod" className="clickable" value={startPeriod} >                
                          <option value="Full Day">Full Day</option> 
                          <option value="AM">AM</option> 
                          <option value="PM">PM</option>                      
                    </select>              
                         
                    <div>End Date</div>          
                    <DatePicker className="datePicker" dateFormat="MM/dd/yy" selected={stringToDate(endLeaveDate)} onChange={date => dateToString(date,2)}  />                                                                     
                    <select onChange={handleEndPeriod} id="enterLeave_endPeriod" className="clickable" value={endPeriod} >                
                          <option value="Full Day">Full Day</option> 
                          <option value="AM">AM</option> 
                          <option value="PM">PM</option>                      
                    </select>             

                    
                    <button id="addLeave" onClick={() => {
                               handleSubmitLeave(false)
                            }}>Insert
                    </button>      

                    <button id="clearLeave" onClick={() => {
                               handleClearLeave()
                            }}>Clear
                    </button>                                      
                    {leaveList.length > 0 ? (
                        <button id="submitLeave" onClick={() => {
                              handleSubmitLeave(true) 
                             }}>Submit
                       </button>):null
                    }
            
               </div>
            

            <table id="enterLeaveTable"> 

                <thead>          
                  <tr className="enterLeave_grid_a">
                    <th>Start Date</th>          
                    <th>Start Period</th>              
                    <th>End Date</th>
                    <th>End Period</th>              
                    <th>No. of Working Day(s)</th>
                    <th>Out Of Office Day(s)</th>
                    <th>Remove</th>                    
                    </tr>                  
                </thead>        
            
            
                <tbody>
                
                    {leaveList.length > 0 ? (
                    leaveList.map((x) => (
                          <tr key={x.id}  className="enterLeave_grid_b">                                                        
                              <td>{isoToShort(x.startLeaveDate) + " (" + weekday[stringToDate(x.startLeaveDate).getDay() ] + ")"}</td>                       
                              <td>{x.startPeriod}</td>                              
                              <td>{isoToShort(x.endLeaveDate) + " (" + weekday[stringToDate(x.endLeaveDate).getDay() ] + ")"}</td>                       
                              <td>{x.endPeriod}</td>                                                            
                              <td>{x.workday}</td>                          
                              <td>{x.calendarDay}</td>                             
                              <td>   
                                  <i
                                    className="fa fa-close clickable"
                                    onClick={() => {
                                      handleDelLeave(x.id)
                                    }}
                                  ></i>
                           </td>                              
                         </tr>             
                    ))) : null}              
                
                </tbody>
            </table>      

     
        </div>
        
      </div>
      <ShowSpinner position={10} />

    </Fragment>
  )
  }

export default EnterLeave 