import React, { Fragment, useState, useEffect } from "react"

const UserProfile = props => {
  const { userProfile, setSuperUserMode, superUserMode} = props
  const [photoURL, setPhotoURL] = useState("")
  
  useEffect(() => {
    setPhotoURL("/api/getPhoto/" + userProfile.email)              
  }, [userProfile.email])

  const toggleSuperUser  = () => {    
    setSuperUserMode(!superUserMode)    
  }        
  
  const switchUser  = () => {    
    window.location =  userProfile.switchUser
  }        
   
  return (
    <Fragment>                    
        
        <div className={"userProfile ".concat(userProfile.databaseSchema === 'dev' ? 'userProfile_dev_color' : 'userProfile_prod_color')}>
            <div className="userProfile_d userProfile_grid_d">
                  <img src={userProfile.databaseSchema === 'dev' ? "static/img/macys_red_icon.png":  "static/img/macys_blue_icon.png"} alt="" height="60"  />
            </div>
            <div className="userProfile_e userProfile_grid_e">                
                e-leave@mmgoverseas
            </div>    
            <div className={"userProfile_b userProfile_grid_b " + (userProfile.superUser ? "userProfile_hover" : "")}            
                  onClick={() => {
                    (userProfile.superUser? switchUser() : void(0)) // do nothing if not superuser
                  }} >      
                  {userProfile.userName}
            </div>  
            <div className="userProfile_c userProfile_grid_c" >
                {userProfile.superUser && superUserMode? (
                    <i className={"fa fa-superpowers" +  (userProfile.superUser? " userProfile_icon ":undefined)}  onClick={() => {toggleSuperUser()}} ></i>
                ) : <i className={"fa fa-user " + (userProfile.superUser? " userProfile_icon": undefined)}  onClick={() => {toggleSuperUser()}} ></i>}          
            </div>        
          <div className="userProfile_a userProfile_grid_a"><img src={photoURL ? photoURL: "static/img/anonymous.jpg"} aria-hidden alt="..." width="60" height="60" /> </div>   
        </div>

             
    </Fragment>
  )
}

export default UserProfile
