import { React, Fragment, useState, useEffect } from "react"
import { trackPromise } from "react-promise-tracker"
import axios from "axios"
 
const OtherLeave = props => {

  // passed parameter
  const {currentRacf, convert2MMDDYY, setRefDetails, convertToLocal, superUserMode} = props

  // variable
  const [refList, setRefList] = useState([])
  const [selectedRef, setSelectedRef] = useState("N/A")
  
  const [leaveType, setLeaveType] = useState("N/A")
  const [entitledDays, setEntitledDay] = useState("N/A")
  const [periodStart, setPeriodStart] = useState("N/A")
  const [periodEnd, setPeriodEnd] = useState("N/A")

  useEffect(() => {

    trackPromise(
      axios({
        url: "/eleave/api/getAllSpecialRef",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({'racf': currentRacf, 'super_mode': superUserMode, 'localTime': convertToLocal(Date.now())} )      
      }
    )
    .then(response => response.data)
    .then(response => {     
      setRefList(response)
    }),
    "getRefList"
    )
  }, [currentRacf, superUserMode, convertToLocal])


  useEffect(() => {

    trackPromise(
      axios({
        url: "/eleave/api/getRefDetails",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({'ref_no': selectedRef} )      
      }
    )
    .then(response => response.data)
    .then(response => {     
      setRefDetails(response[0])
      setLeaveType(response[0].leave_name)
      setEntitledDay(response[0].entitled_days.toFixed(1))
      setPeriodStart(convert2MMDDYY(response[0].period_start))
      setPeriodEnd(convert2MMDDYY(response[0].period_end))
    }),
    "getRefDetails"
    )
  }, [selectedRef, superUserMode, convert2MMDDYY, setRefDetails])

  const handleRef = event => {   
    const { value } = event.target    
    setSelectedRef(value)
  }

  return (
    <Fragment>

     <div className="separator">Select Other Leave</div>

     <div className="otherleave_grid">

        <div className="otherleave_area_a otherleave_grid_a">
          Reference # : 
          <select onChange={handleRef} id="specialLeave_select" className="clickable" value={selectedRef}>  
          <option value="N/A" disabled> Click to select your requested leave </option>
           {refList.map((ref) => (<option key={ref.ref_no} value={ref.ref_no}> {ref.ref_no}</option>))}
          </select>
        </div>   

        <div className="otherleave_area_c otherleave_grid_c" style={{ borderBottom: "2px solid gray", marginLeft: 0, marginRight: 0 }}>
          <div><strong>Leave Details</strong></div>
        </div>


        <div className="otherleave_area_d otherleave_grid_d">
          Leave Type : {leaveType}
        </div>     

        <div className="otherleave_area_e otherleave_grid_e">
          Entitled Days : {entitledDays}
        </div>     

        <div className="otherleave_area_f otherleave_grid_f">
          Allowed Period: {periodStart} - {periodEnd}
        </div> 


     </div>

    </Fragment>
  )
}
export default OtherLeave
