import { React, Fragment, useState, useEffect} from "react"
import { trackPromise } from "react-promise-tracker"
import axios from "axios"

import DatePicker from 'react-datepicker'

const EnterRequest = props => {

  // passed parameter
  const {office, leaveType, setDisplayAlert, userList} = props   

  // new add in this page
  const [entitledDay, setEntitledDay] = useState("")
  const [racf, setRACF] = useState("")
  const [newRefNo, setNewRefno] = useState("")
  const [accumulated, setAccumulated] = useState("")
  const [exclusive, setExclusive] = useState("")
  const [selectedOfc, setSelectedOfc] = useState("")
  const [selectedType, setSelectedType] = useState("")
  const [refDate, setRefDate] = useState("")
  const [periodStart, setperiodStart] = useState("")
  const [periodEnd, setperiodEnd] = useState("")

  // init date
  const currentDate = new Date()
  const year = currentDate.getFullYear()

  // init userList

  // This is needed to mitigate the dates between browser (local time) and server (Mongo DB)
  // When date (date.getTime) is selected, the date is based on UTC 00:00.  That could be the next day. 
  // Therefore, the offset has to be calcualted and be used to minus the date  
  const dateToString = (date, pos) => {      
    if (!date) { 
      if (pos ===1) {
        setRefDate("")
      }
      if (pos ===2) {
        setperiodStart("")
        setperiodEnd("")
      }
      if (pos ===3) {
        setperiodEnd("")
      }

      return 
    }
    const userTimezoneOffset = date.getTimezoneOffset() * 60000;
    const d = new Date(date.getTime() - userTimezoneOffset);
    //console.log('d', d.toISOString().substring(0,10))
    if (pos ===1) {
      setRefDate(d.toISOString().substring(0,10))
    }
    if (pos ===2) {
      setperiodStart(d.toISOString().substring(0,10))    
      setperiodEnd(d.toISOString().substring(0,10))     
    }
    if (pos ===3) {
      setperiodEnd(d.toISOString().substring(0,10))     
    }
  }
  
  // This is needed to mitigate the dates between browser (local time) and server (Mongo DB)
  // When date (date string) is captured, it is based on UTC 00:00. So the local time could become the previous day. 
  // Therefore, the offset has to be calcualted and be used to add to the date string   

  const stringToDate = dateString => {    
    let d = dateString       
    if (d === "") {      
      return
      //d = new Date()    
      //const userTimezoneOffset = d.getTimezoneOffset() * 60000;
      //d = new Date(d.getTime() - userTimezoneOffset);                 
    }
    else {
      d = new Date(dateString)         
      const userTimezoneOffset = d.getTimezoneOffset() * 60000;
      d = new Date(d.getTime() + userTimezoneOffset);               
    }
    return d        
  }

  useEffect(() => {

    trackPromise(
      axios({
        url: "/eleave/api/specialLeaveRefNo",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({'Office': selectedOfc, 'Year': year} )      
      }
    )
    .then(response => response.data)
    .then(response => {          
      setNewRefno(response)
    }),
    "getNewRefno"
    )
  }, [year, selectedOfc, newRefNo])

  const handleAccumulated =   event => {   
    const { value } = event.target    
    setAccumulated(value)             
  }

  const handleExclusive =   event => {   
    const { value } = event.target    
    setExclusive(value)             
  }

  const handleOffice =   event => {   
    const { value } = event.target    
    setSelectedOfc(value)
  }

  function handleLeaveType(event) {
    const selectedValue = event.target.value
    setSelectedType(selectedValue)
  }

  function handleEntitledDay(event) {
    const { value } = event.target 
    setEntitledDay(value)
  }

  function handleRACF(event) {
    const { value } = event.target 
    const uppercaseValue = value.toUpperCase()
    setRACF(uppercaseValue)
  }

  function handleRefNo(event) {
    const { value } = event.target 
    setNewRefno(value)
  }

  const otherleave = Object.values(leaveType).map((item) => ({
    value: item.leave_type_id,
    label: item.leave_type,
  }))


  const handleSubmit = event => { 
    
    const specialLeaveRequest = {
      "office": selectedOfc,
      "racf": racf,
      "year": year,
      "ref_no": newRefNo,
      "leave_type": selectedType,
      "entitled_days": entitledDay,
      "ref_date": refDate,
      "period_start": periodStart,
      "period_end": periodEnd,
      "accumulated": accumulated,
      "excluded_holidays": exclusive
    }

    if (!window.confirm('Are you sure you want to submit?')) {         
      return null     
    }
    trackPromise(
      axios({
        url: "/eleave/api/submitRequest",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },          
        data: JSON.stringify(specialLeaveRequest)      
      }
    )
    .then(response => response.data)
    .then(response => {
      setDisplayAlert({ message: "Requisition submitted successfully ", position: 4, timeout: 4000, color: "alert__green" })
      clearAll()
    })
    .catch(error =>  {                             
      //console.log("Error status", error.response.status,  error.response.data.error_message)     // can also checking using error.response.status 
      setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 4000, color: "alert__red" })
    }),
    "otherLeave"
    )
  }


  const clearAll = event => {
    setAccumulated("")
    setExclusive("")
    setSelectedOfc("")
    setRACF("")
    setSelectedType("")
    setEntitledDay("")
    setRefDate("")
    setperiodStart("")
    setperiodEnd("")
  }

  return (
    <Fragment>
        
      <div>
            <div className="separator">Submit Reference</div>
            
            <div className="sp_type_grid">

                <div className="sp_type_area_a sp_type_grid_a">
                Office:
                <select style={{width: '5rem', height:"25px"}} onChange={handleOffice} id="specialLeave_select" className="clickable" value={selectedOfc} >            
                <option value="" disabled> - </option>
                {office.map((ofc) => (<option key={ofc} value={ofc}> {ofc}</option>))}
                </select>
                </div>
                
                <div className="sp_type_area_b sp_type_grid_b">    
                Applicant:
                <select style={{width: '30rem', height:"25px"}} onChange={handleRACF} id="specialLeave_select" className="clickable" value={racf} >                
                <option value="" disabled> - </option>
                {userList && userList.map((user, index) => (
                  <option key={index} value={user.racf}>
                    {user.name} ({user.racf})
                  </option>
                ))}
                </select>
                </div>        
                
                <div className="sp_type_area_c sp_type_grid_c">
                Approval #:
                <input onChange={handleRefNo} value={newRefNo} disabled></input>
                </div>

                <div className="sp_type_area_d sp_type_grid_d">
                Leave Type:
                <select value={selectedType} onChange={handleLeaveType}>
                <option value="" disabled> - </option>
                  {otherleave.map((lve) => (
                    <option key={lve.value} value={lve.value}>
                      {lve.label}
                    </option>
                  ))}
                </select>
                </div>

                <div className="sp_type_area_e sp_type_grid_e">
                Entitled Days:
                <input type="number" min={0.5} max={999} step={0.5} id="specialLeave_number" onChange={handleEntitledDay} value={entitledDay}></input>
                </div>

                <div className="sp_type_area_f sp_type_grid_f">
                Ref Date:
                <DatePicker
                    portalId="datePicker"
                    selected={stringToDate(refDate)}
                    onChange={date => dateToString(date,1)}
                    dateFormat="MM/dd/yyyy"
                    placeholderText='Click to select a date'
                    className="custom-datepicker"
                />
                </div>

                <div className="sp_type_area_g sp_type_grid_g">
                Period Start:
                <DatePicker
                    portalId="datePicker"
                    selected={stringToDate(periodStart)}
                    onChange={date => dateToString(date,2)}
                    dateFormat="MM/dd/yyyy"
                    placeholderText='Click to select a date'
                />
                </div>

                <div className="sp_type_area_h sp_type_grid_h">
                Period End:
                <DatePicker
                    portalId="datePicker"
                    selected={stringToDate(periodEnd)}
                    onChange={date => dateToString(date,3)}
                    dateFormat="MM/dd/yyyy"
                    placeholderText='Click to select a date'
                />
                </div>

                <div className="sp_type_area_i sp_type_grid_i">
                Accumulated:
                <select style={{width: '5rem', height:"25px"}} onChange={handleAccumulated} id="specialLeave_select" className="clickable" value={accumulated} >            
                <option value="">-</option>
                <option value="True">Yes</option>
                <option value="False">No</option>
                </select>
                </div>

                <div className="sp_type_area_j sp_type_grid_j">
                Holiday/Weekend:
                <select style={{width: '8rem', height:"25px"}} onChange={handleExclusive} id="specialLeave_select" className="clickable" value={exclusive} >
                <option value="">-</option>
                <option value="True">Exclusive</option>
                <option value="False">Inclusive</option>
                </select>
                </div>

            </div>    

            <button id="specialLeave_submit" onClick={handleSubmit}>
                  Submit
            </button>
            <button id="specialLeave_clear" onClick={clearAll}>
                  Clear
            </button>
      </div>
    </Fragment>
  )
  }

export default EnterRequest